# Code Generated by Sidekick is for learning and experimentation purposes only.

from datetime import UTC, datetime

from fraud_service.app.schemas.fraud import FraudCheckRequest


def extract_features(
        request: FraudCheckRequest,
        velocity_counts: dict,
        exp_months_remaining: int,
        is_first_card_use: bool,
        email_domain_risk: float,
) -> list[float]:
    """
    Converts transaction data into numbers for ML model.

    Start small: 13 features
    Stripe uses 500+ features (build up over time)
    """
    now = datetime.now(tz=UTC)

    return [
        # Amount features
        request.amount / 100.0,  # Amount in dollars
        1.0 if request.amount < 100 else 0.0,  # Is micro transaction
        1.0 if (request.amount >= 20000 and request.amount % 10000 == 0) else 0.0,

        # Time features
        float(now.hour),  # Hour of day (fraud spikes at night)
        float(now.weekday()),  # Day of week

        # Card features
        float(exp_months_remaining),  # Card expiry months remaining
        1.0 if is_first_card_use else 0.0,  # First time card used

        # Velocity features
        float(velocity_counts.get("card_velocity_1h", 0)),
        float(velocity_counts.get("ip_velocity_1h", 0)),
        float(velocity_counts.get("customer_tx_count", 0)),
        float(velocity_counts.get("customer_failed_count", 0)),

        # Customer features
        email_domain_risk,  # Disposable email?

        # Amount vs history ratio (high amount relative to history = risky)
        request.amount / max(velocity_counts.get("customer_tx_count", 1), 1) / 100.0,
    ]
